package com.xiaomiscalesync.xiaomi

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test

/**
 * Known-answer tests for [Rc4] against fixtures generated by
 * `scripts/gen_vectors.py --micloud`:
 *
 * - two published raw-RC4 vectors (Wikipedia "RC4" test vectors),
 * - the drop-1024 transform the reference client applies to the signed
 *   nonce before encrypting parameters / decrypting responses
 *   (`r.encrypt(bytes(1024))` in token_extractor.py's
 *   `encrypt_rc4` / `decrypt_rc4`).
 */
class Rc4Test {

    private val vectors: List<MiCloudVector.Rc4> =
        MiCloudVectors.load().filterIsInstance<MiCloudVector.Rc4>()

    private fun fixture(name: String): MiCloudVector.Rc4 = vectors.first { it.name == name }

    @Test
    fun publishedRawRc4KnownAnswersMatch() {
        // Pinned literals, independent of the committed fixture file.
        val keyPlaintext = fixture("rc4_key_plaintext")
        assertEquals(0, keyPlaintext.drop)
        assertEquals("bbf316e8d940af0ad3", keyPlaintext.ciphertext.toHex())
        assertArrayEquals(
            keyPlaintext.ciphertext,
            Rc4.apply(keyPlaintext.key, keyPlaintext.plaintext),
        )

        val secretAttack = fixture("rc4_secret_attack")
        assertEquals("45a01f645fc35b383552544b9bf5", secretAttack.ciphertext.toHex())
        assertArrayEquals(
            secretAttack.ciphertext,
            Rc4.apply(secretAttack.key, secretAttack.plaintext),
        )
    }

    @Test
    fun drop1024MatchesGoldenVector() {
        val f = fixture("rc4_drop1024")
        assertEquals(1024, f.drop)
        assertArrayEquals(f.ciphertext, Rc4.applyDrop(f.key, f.plaintext))
    }

    @Test
    fun drop1024EqualsReferenceEncryptBytes1024Idiom() {
        // The reference does `r.encrypt(bytes(1024))` and then encrypts the
        // payload in the same RC4 stream: encrypting 1024 zero bytes first
        // consumes exactly those keystream bytes. Both must agree.
        val f = fixture("rc4_drop1024")
        val viaIdiom = Rc4.apply(f.key, ByteArray(1024) + f.plaintext)
            .copyOfRange(1024, 1024 + f.plaintext.size)
        assertArrayEquals(f.ciphertext, viaIdiom)
    }

    @Test
    fun applyIsASymmetricStreamCipher() {
        val f = fixture("rc4_drop1024")
        val ciphertext = Rc4.applyDrop(f.key, f.plaintext)
        assertArrayEquals(f.plaintext, Rc4.applyDrop(f.key, ciphertext))
    }

    @Test
    fun emptyKeyIsRejected() {
        assertThrows(IllegalArgumentException::class.java) {
            Rc4.apply(ByteArray(0), byteArrayOf(1, 2, 3))
        }
    }

    private fun ByteArray.toHex(): String =
        joinToString("") { "%02x".format(it.toInt() and 0xFF) }
}
